package mrpapermoon.whisper.screenimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport dagger.hilt.android.lifecycle.HiltViewModelimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.launchimport mrpapermoon.whisper.actors.MeshActionimport mrpapermoon.whisper.actors.MeshActorimport mrpapermoon.whisper.actors.MeshStateimport javax.inject.Inject@HiltViewModelclass SplashViewModel @Inject constructor(	private val meshActor: MeshActor,) : ViewModel() {	private val _state = MutableStateFlow<MeshState>(MeshState.Idle)	val meshState: StateFlow<MeshState> = _state.asStateFlow()	init {		viewModelScope.launch {			meshActor.collect {				_state.emit(it)			}		}	}	fun sendAction(action: MeshAction) {		meshActor.send(action)	}}